`))y(p);if(m=m.trim(),!m)throw new Error("这次什么都没说，再试一次；老是这样就去牌库换个型号");return m}const Ax=n=>n.split("、"),KS=[["愚者","新的开始、随心、不设防","想到就去做，先别问结果。这是一个轻装上路的时刻。","犹豫、冒失、没准备好","不是不想，是还没准备好。慢一点，看清脚下再走。"],["魔术师","主动、有话想说、说到做到","有话想说，也有办法让你听见。想要的，会主动去促成。","心口不一、话没传到、使不上力","想说的没说到位，或者有想法却没落到实处。慢一点，先把一句话说清楚。"],["女祭司","直觉、安静、心里有数","答案不在话里，在感觉里。安静下来，其实早就知道了。","猜不透、藏着话、忽略直觉","有些话没说出口。别急着追问，也别假装没感觉到。"],["皇后","被爱、丰盛、温柔","被好好照顾着，也有余力去照顾。此刻是柔软而富足的。","付出太多、依赖、忘了自己","给得太多，自己那份被落下了。先把自己照顾好。"],["皇帝","可靠、担当、有分寸","稳稳地在那里，说到的会做到。可以放心倚靠。","太硬、控制、不肯低头","绷得太紧，习惯自己扛。松一点，不必事事都掌握。"],["教皇","承诺、规矩、指引","认真而正式的心意。愿意照着约定，一步一步来。","不想被框住、各有想法、打破惯例","不想照着旧规矩走。可以有属于你们自己的方式。"],["恋人","相爱、选择、心意相通","心是朝着彼此的。这是一次发自内心的选择。","摇摆、没说清、步调不一","步调暂时没对上。把真正想要的说清楚，比猜更有用。"],["战车","坚定、向前、掌握方向","方向已经定了，正朝那里去。有决心，也拿得住自己。","拉扯、用力过猛、方向不明","两股力气在互相拉扯。先停一下，确认要去哪儿。"],["力量","温柔的勇气、耐心、包容","不靠硬撑，靠的是耐心和温柔。慢慢来，是驯服得了的。","没底气、压着情绪、自我怀疑","对自己有点没信心。不需要逞强，承认累了也可以。"],["隐士","独处、沉淀、向内看","需要一点自己的时间，把事情想明白。不是疏远，是在沉淀。","封闭、太孤单、该出来了","一个人待得太久了。可以开口，不必什么都自己消化。"],["命运之轮","转机、缘分、顺势","事情正在往好的方向转。有些相遇，本来就会发生。","不顺、时机未到、起伏","眼下有点不顺，但轮子还在转。这只是其中一段。"],["正义","坦诚、公平、有因有果","坦白、对等，说话算数。你怎么待它，它就怎么回应你。","不对等、回避、心里不平","有点失衡，或有话没摊开说。把账算清，心才放得下。"],["倒吊人","等待、换个角度、甘愿","暂时停着，不是坏事。换一个角度看，会看到别的东西。","僵着、白等、不肯放","卡在原地太久了。有些坚持可以放下，才有新的可能。"],["死神","结束、翻篇、新的阶段","一个阶段走完了，为新的腾出位置。这是翻页，不是失去。","舍不得、拖着、害怕改变","明知该翻篇，却还握着不放。松手会比想象中轻。"],["节制","平衡、磨合、刚刚好","两边在慢慢调和，找到刚刚好的温度。不急，顺着来。","失衡、过头、急躁","有点过了，或有点不够。把节奏调回让自己舒服的位置。"],["恶魔","沉迷、强烈的吸引、放不下","很强的吸引，也很难抽身。看清是什么让你离不开。","松绑、清醒、挣脱","正在从缠住自己的东西里松开。清醒过来，是好事。"],["高塔","突变、打破、真相","不稳的东西会塌，来得突然，却也痛快。塌掉之后才看得见地基。","勉强撑着、害怕变动、躲过一劫","心里知道哪里不对，只是还在撑。早点面对，震动会小一些。"],["星星","希望、疗愈、心愿","安静而确定的希望。慢慢在好起来，心愿是被听见的。","灰心、不敢期待、缺少信心","有点不敢期待了。光还在，只是这会儿被云挡着。"],["月亮","朦胧、梦境、想太多","看不太清，容易胡思乱想。这也是梦和直觉的牌：害怕的那些，多半只是影子。","雾散、看清、安下心","雾在散，事情比想的简单。可以把心放回肚子里了。"],["太阳","快乐、坦率、一切顺利","明亮、坦率、暖洋洋的。此刻是可以放心开心的。","小乌云、没那么尽兴、期待偏高","开心还在，只是打了点折扣。把期待放低一点就好。"],["审判","醒悟、回应、重新开始","一个被叫醒的时刻。过去的可以放下，重新来过。","自责、放不下过去、迟迟不回应","还在跟过去的自己过不去。原谅一下，才走得动。"],["世界","圆满、完成、抵达","一段路走到了头，是圆满的。可以安心收下这个结果。","差一点、未完成、舍不得结束","只差最后一点没收尾。把它做完，再开始下一段。"],["权杖一","热情、冲动、新的火花","一股想靠近、想开始的冲动。火已经点着了。","提不起劲、起了头没下文、时机未到","有心，却还没动起来。等火再旺一点。"],["权杖二","规划、远望、做决定","在想以后的事，手里已经有了打算。","举棋不定、不敢走远、计划搁置","计划停在纸上。害怕变化，就先迈一小步。"],["权杖三","期待、展望、等着回音","事情已经铺开，正望着远处等回音。会有消息的。","回音迟到、进展慢、耐心不够","比预想的慢。不是没有回应，是还在路上。"],["权杖四","安稳、庆祝、像家一样","一个可以停下来庆祝的地方。安心、踏实，像回到家。","不够安定、小别扭、归属感不足","还差一点安定感。有些小别扭，说开就好。"],["权杖五","争执、较劲、各说各的","你一言我一语，谁也不让谁。吵闹，但不是恶意。","不想吵、各退一步、憋着","不想再争了。各退一步，或者把憋着的话好好说。"],["权杖六","被认可、得意、好消息","被看见、被肯定的时候。有值得骄傲的好消息。","没被看见、落空、在意评价","努力没被看到，有点失落。不需要别人点头才算数。"],["权杖七","坚持、守住立场、不退让","有压力，但站得住。为在意的东西守着位置。","撑累了、想放弃、防备过头","守得太累了。不是每一处都要寸步不让。"],["权杖八","很快、消息到来、直奔而去","事情来得很快，消息正在路上。心是直奔过去的。","延迟、卡住、急不来","慢下来了，消息卡在半路。这件事急不来。"],["权杖九","戒备、撑到最后、受过伤","累，也有防备，但还站着。只差最后一段了。","撑不住、防备太重、该歇了","绷得太久了。放下戒备歇一歇，没有人在逼你。"],["权杖十","扛太多、压力、责任","一个人扛了太多，走得很吃力。可以分一些出去。","卸下、撑不动了、学会放手","终于想把担子放下来。不必什么都自己背。"],["权杖侍从","好奇、跃跃欲试、新消息","带着好奇和兴致，想试一试。会有让人眼睛一亮的消息。","三分钟热度、没消息、沉不住气","兴致来得快去得也快。先别急，看能不能坚持几天。"],["权杖骑士","冲动、热烈、说走就走","热烈而直接，想到就行动。来得快，也很有冲劲。","急躁、忽冷忽热、冲过头","忽冷忽热，冲得太急。慢下来，热度才留得住。"],["权杖王后","自信、温暖、有魅力","温暖又笃定，自带光亮。知道自己要什么，也大方地给。","逞强、吃醋、没自信","有点逞强，或在暗暗吃味。不用证明什么，本来就够好。"],["权杖国王","有担当、远见、带头","有魄力，也有远见，愿意为说过的话负责。","霸道、急脾气、说得多做得少","脾气上来了，想什么都自己说了算。先听听对方。"],["圣杯一","心动、满溢、新的感情","心里满得要溢出来。一份新的、干净的喜欢。","压着感情、空落落、不敢表达","感情压着没说，心里有点空。让它流出来一点。"],["圣杯二","两情相悦、对等、连接","两个人举杯相对，心意是对等的。连上了。","错位、小隔阂、没接上","暂时没接上频道。一点小隔阂，说一句软话就过去。"],["圣杯三","开心、分享、热闹","值得一起高兴的事。被朋友和笑声围着。","被冷落、玩过头、有外人掺和","热闹里有点落单。也可能是别人的声音太多了。"],["圣杯四","没兴致、发呆、视而不见","有点闷，提不起劲。眼前其实有一杯新的，只是还没抬头。","回过神、愿意接受、重新在意","回过神来了，开始愿意接住递过来的东西。"],["圣杯五","失落、遗憾、盯着失去的","在为打翻的难过。回头看看，身后还有两杯是好的。","走出来、原谅、重新看见","慢慢走出来了。遗憾还在，但已经看得见剩下的好。"],["圣杯六","怀念、单纯、旧时光","想起以前的事，心里软软的。一份不带算计的心意。","困在回忆、该往前了、太理想化","总想回到从前。那时候很好，现在也值得好好过。"],["圣杯七","选择太多、幻想、拿不定","眼前浮着很多可能，一时分不清哪个是真的。先别急着选。","看清、做了决定、回到现实","幻想散了，知道自己真正要哪一个了。"],["圣杯八","转身离开、寻找、不再将就","已经不够了，于是转身去找更想要的。不是赌气。","舍不得走、犹豫、走了又回头","想走又舍不得。弄清楚是留恋，还是真的还有东西在。"],["圣杯九","心满意足、愿望成真、自在","想要的得到了，心里美滋滋的。这是愿望会成真的那张牌。","不知足、表面满足、贪多","得到了，却没想象中开心。问问自己真正缺的是什么。"],["圣杯十","幸福、圆满的感情、家","彩虹底下的一家人。感情上想要的，都在这里了。","差一点圆满、小摩擦、期待不一","离圆满只差一点，卡在一些小摩擦上。别让它们盖过好的。"],["圣杯侍从","心意、害羞、小惊喜","一份有点害羞的心意，想给你一个小惊喜。","玻璃心、孩子气、不敢说","有点敏感，话到嘴边又咽回去。需要被哄一下。"],["圣杯骑士","浪漫、主动示好、带着心意而来","捧着心意慢慢走过来。温柔、浪漫，是认真的。","说得好听、飘忽、落不了地","话很动听，行动没跟上。看做了什么，而不只是说了什么。"],["圣杯王后","体贴、懂你、温柔地接住","很懂你的情绪，安静地接住。被温柔对待着。","情绪化、想太多、委屈自己","情绪有点满，容易多想。先顾好自己的心。"],["圣杯国王","沉稳、包容、情绪稳定","感情很深，但稳得住。能包容你的起伏。","压抑、冷处理、情绪起伏","把情绪压着，表面平静。冷下来不是不在意，是不知道怎么说。"],["宝剑一","清醒、说实话、想明白了","一下子想明白了。把话说清楚，干净利落。","想不清、话说重了、误会","脑子有点乱，话也容易说重。想清楚再开口。"],["宝剑二","僵持、不想选、回避","蒙着眼不想做决定。两边都不想伤，就先僵着。","不得不面对、做出选择、说开了","躲不下去了，终于肯看一眼。选了，反而轻松。"],["宝剑三","心痛、难过、被话刺到","被刺痛了，是真的难过。让它疼一会儿，雨会停的。","慢慢愈合、放下、说出来了","伤口在收了。说出来、哭出来，就过去一半。"],["宝剑四","休息、暂停、养一养","需要安静地歇一歇。不是不理你，是在回血。","歇够了、睡不好、被迫停下","休息得差不多了，或是一直没歇好。该动一动了。"],["宝剑五","赢了也不开心、嘴硬、伤和气","争赢了，场面却冷了。有些输赢不值得。","想和好、认个错、放下输赢","不想再争了，愿意先低头。和好比赢重要。"],["宝剑六","离开难处、慢慢好转、过渡","正从难熬的地方慢慢划出去。水会越来越平。","走不出来、旧事重提、拖着","还没完全离开那片水。旧的事需要好好了结。"],["宝剑七","有所隐瞒、绕着走、小心思","有些事没明说，绕着走。不一定是坏心，只是没摊开。","说实话、藏不住了、良心不安","藏着的事想说出来了。坦白会让彼此都轻松。"],["宝剑八","被困住、自己吓自己、无力","觉得动不了，其实绳子没那么紧。困住人的多半是念头。","松绑、看见出路、拿回主动","发现自己其实走得出去。一步一步来。"],["宝剑九","焦虑、失眠、往坏处想","夜里想得太多，越想越怕。天亮了会不一样。","说出来就好了、担心落空、慢慢放松","最担心的没有发生。把心事说给人听，会轻很多。"],["宝剑十","到底了、结束、最糟的已经过去","已经是最低点了，不会更糟。天边开始亮了。","缓过来、爬起来、不再重蹈覆辙","在慢慢缓过来。那一段结束了，不必再回去。"],["宝剑侍从","好奇、观察、想知道真相","在留意你、打听你，想弄明白。脑子转得很快。","多疑、嘴快、道听途说","想得多，话出口太快。别拿没证实的事吓自己。"],["宝剑骑士","直接、急着说、雷厉风行","风风火火地冲过来，有话直说。很快，也很冲。","太冲、说话伤人、没想好就做","冲得太急，话不留余地。缓一缓再说。"],["宝剑王后","清醒、独立、界限分明","看得很清楚，不吃糊弄。温柔，但有原则。","嘴硬心软、太苛刻、用冷淡保护自己","用冷淡把自己包起来了。不必那么硬。"],["宝剑国王","理性、讲道理、靠得住的判断","冷静、讲理，说的话有分量。可以认真听一听。","太冷、讲理不讲情、固执","道理讲得太多，温度少了。这时候更需要一句软话。"],["星币一","实在的开始、机会、落地","一个摸得着的好机会。种子已经在手里。","机会溜走、准备不足、不踏实","机会还没接稳。先把基础打牢。"],["星币二","兼顾、灵活、忙里偷闲","手里抛着两头，忙但还转得动。在努力腾出时间。","顾不过来、手忙脚乱、失衡","事情太多，快接不住了。得放下一个球。"],["星币三","合作、用心经营、被认可","一起把事情一点点做好。认真是被看见的。","配合不上、各做各的、不被重视","步调不太一致。坐下来对一对想法。"],["星币四","抓紧、安全感、舍不得","把在意的东西抱得很紧，怕失去。是在乎，也是不安。","松手、太计较、愿意付出","握得太紧了，或终于肯松开一点。给出去也不会少。"],["星币五","缺乏、被冷落、难处","有点冷，有点难。别只顾着低头走，旁边的窗是亮的。","缓过来、有人伸手、最难的过去了","最冷的那段过去了。接受帮助并不丢人。"],["星币六","给予、被照顾、礼尚往来","有来有往的善意。愿意给，也给得起。","不对等、有条件的好、单方面付出","给和收不太对等。看看是不是总是一边在出力。"],["星币七","等待结果、耐心、值不值得","种下去了，在等它长。停下来看看，是值得的。","心急、没见回报、想放弃","等得有点急了。有些东西就是长得慢。"],["星币八","专注、认真、一点点打磨","低着头认真地做，一下一下打磨。心思都花在这上面。","没耐心、敷衍、太累了","有点磨不下去了。不是不在意，是累了。"],["星币九","自在、独立、享受成果","一个人也过得很好，从容而自在。值得享受自己挣来的一切。","逞强、表面光鲜、有点孤单","看着什么都不缺，心里有点空。可以让人走进来。"],["星币十","安稳的未来、家、长久","长长久久、有家有底的安稳。是奔着以后去的。","家里的事、不够稳、长远的顾虑","对以后有些顾虑，多半是现实层面的。可以慢慢安排。"],["星币侍从","认真学、踏实、好消息","一步一步、很认真地在学怎么做好。会有实在的好消息。","光想不做、分心、拖延","想得多，做得少。从最小的一件事开始。"],["星币骑士","可靠、慢但稳、说到做到","不快，但一步都不会少。靠得住，会一直在。","太慢、一成不变、死板","稳是稳，就是太慢太闷了。需要一点新鲜的。"],["星币王后","会照顾人、踏实、把日子过好","把人和日子都照顾得很好。温暖、实在、让人安心。","顾此失彼、太操心、忽略自己","操心得太多，把自己落下了。也该被照顾一下。"],["星币国王","稳重、给得起、可以托付","稳稳当当，给得起承诺，也兑现得了。可以托付。","只看现实、固执、用东西代替陪伴","给了很多实在的，却少了陪伴。有些东西是换不来的。"]],Re=KS.map(([n,i,r,o,d])=>({name:n,up:Ax(i),upLine:r,rev:Ax(o),revLine:d})),fs=Re.length,JS=[{name:"大阿卡纳",from:0,to:22},{name:"权杖",from:22,to:36},{name:"圣杯",from:36,to:50},{name:"宝剑",from:50,to:64},{name:"星币",from:64,to:78}],ud=n=>n<22?-1:Math.floor((n-22)/14),tm=n=>n<22?n:(n-22)%14+1,WS=["0","I","II","III","IV","V","VI","VII","VIII","IX","X","XI","XII","XIII","XIV","XV","XVI","XVII","XVIII","XIX","XX","XXI"],FS=["侍从","骑士","王后","国王"],IS=n=>n<22?WS[n]:tm(n)<=10?String(tm(n)):FS[tm(n)-11],b2=["match","one","heart","topic","call"],PS={day:0,one:0,heart:2,time:2,link:3,match:1,topic:1,call:4},ea={day:{name:"今日一张",hint:"今天的牌",pos:["今天"]},match:{name:"对一对 · 三张",tag:"开场",when:"每场开头做一次。三张像不像他，像就是连上了",hint:"看看连上的是不是他",pos:["他的性子","他说话的样子","他此刻在做什么"]},one:{name:"一张",when:"问一个具体的问题，听他一句回应",hint:"一个问题，一张牌",pos:["他的回应"]},heart:{name:"三张 · 他的心",when:"想知道他此刻怎么样、对你是什么感受",hint:"此刻的他、他的感受、他想说的话",pos:["此刻的他","他的感受","他想说的话"]},topic:{name:"他想说的话 · 四张",when:"不问具体的事，让他自己挑话题。第一张是话题，后三张是他想说的",hint:"话题牌，后面三张是他想说的话",pos:["话题牌","他想说的","他想说的","他想说的"]},call:{name:"连线 · 五张",tag:"读着不对劲时用",when:"像打电话前先看信号。牌读着别扭、前后对不上时抽：信号好不好，你和他各自怎么样，他那边方不方便",hint:"信号、你、他、他那边、他先说的话",pos:["信号","你","他","他那边","他先说的话"]},link:{name:"连线 · 四张",tag:"不顺的时候用",when:"回答怪怪的、前后对不上时，看看是线上的气氛、你的状态，还是他那边的缘故",hint:"这条线、我、他、他的回应",pos:["这条线","我","他","他的回应"]},time:{name:"三张 · 时间",hint:"过去、现在、接下来",pos:["过去","现在","接下来"]}},e4=["你现在在想什么？","你怎么看我们现在的关系？","有什么想对我说的吗？","今天过得怎么样？","你最喜欢我哪一点？","想和我一起做什么？","我最近的状态，你怎么看？","这件事我该怎么做？","你想我的时候会做什么？","接下来的日子，我们会怎样？"];function k2(n){const i=fs,r=new Uint32Array(i*2);try{crypto.getRandomValues(r)}catch{for(let d=0;d<r.length;d++)r[d]=Math.floor(Math.random()*2**32)}const o=Array.from({length:i},(d,f)=>f);for(let d=i-1;d>0;d--){const f=r[d]%(d+1);[o[d],o[f]]=[o[f],o[d]]}return o.map((d,f)=>({c:d,...n&&r[i+f]%2===1?{r:!0}:{}}))}const N2=n=>n.split(" "),t4=N2("开心 坦率 沉默 宠着你 认真 认真 温柔 坚定 温柔 沉默 开心 认真 冷静 冷静 温柔 黏人 着急 温柔 犹豫 开心 认真 坚定 开心 认真 坦率 开心 逗你 得意 坚定 着急 有点累 有点累 逗你 着急 坦率 坚定 温柔 温柔 开心 沉默 委屈 撒娇 犹豫 冷静 开心 宠着你 撒娇 温柔 心疼 宠着你 坦率 沉默 委屈 有点累 嘴硬 冷静 别扭 犹豫 着急 有点累 逗你 着急 冷静 认真 认真 开心 认真 吃醋 委屈 宠着你 冷静 认真 坦率 坚定 认真 坚定 宠着你 坚定"),a4=N2("犹豫 嘴硬 别扭 委屈 嘴硬 逗你 犹豫 着急 有点累 别扭 有点累 委屈 别扭 犹豫 着急 冷静 嘴硬 有点累 温柔 逗你 委屈 犹豫 犹豫 犹豫 着急 别扭 别扭 委屈 有点累 着急 有点累 委屈 逗你 嘴硬 吃醋 嘴硬 别扭 别扭 吃醋 认真 温柔 撒娇 认真 犹豫 嘴硬 委屈 委屈 逗你 委屈 沉默 嘴硬 认真 温柔 有点累 哄你 犹豫 坦率 坚定 温柔 温柔 嘴硬 嘴硬 别扭 嘴硬 犹豫 有点累 别扭 嘴硬 温柔 委屈 着急 有点累 嘴硬 犹豫 逗你 沉默 心疼 嘴硬"),S2=n=>(n.r?a4:t4)[n.c]??"",n4=(n,i)=>k2(n).filter(r=>!i.includes(r.c)),l4=`
